434	// DownloadCategory is a download directory category that files can be routed to by extension
435	type DownloadCategory struct {
436		Name       string   `json:"name"`                 // Name is the category display name, empty for built-in categories that use NameKey
437		Path       string   `json:"path"`                 // Path is the download directory of the category
438		NameKey    string   `json:"nameKey,omitempty"`    // NameKey is the i18n key of the built-in category name
439		IsBuiltIn  bool     `json:"isBuiltIn,omitempty"`  // IsBuiltIn marks the category as built-in
440		IsDeleted  bool     `json:"isDeleted,omitempty"`  // IsDeleted marks the built-in category as deleted
441		Extensions []string `json:"extensions,omitempty"` // Extensions is the file extension list routed to the category, without leading dots
442	}
443	
444	type DownloaderProxyConfig struct {
445		Enable bool `json:"enable"`
446		// System is the flag that use system proxy
447		System bool   `json:"system"`
448		Scheme string `json:"scheme"`
449		Host   string `json:"host"`
450		Usr    string `json:"usr"`
451		Pwd    string `json:"pwd"`
452	}
453	
454	func (cfg *DownloaderProxyConfig) ToHandler() func(r *http.Request) (*url.URL, error) {
455		if cfg == nil || cfg.Enable == false {
456			return nil
457		}
458		if cfg.System {
459			safeProxyReloadConf()
460			return ieproxy.GetProxyFunc()
461		}
462		if cfg.Scheme == "" || cfg.Host == "" {
463			return nil
464		}
465		return http.ProxyURL(util.BuildProxyUrl(cfg.Scheme, cfg.Host, cfg.Usr, cfg.Pwd))
466	}
467	
468	// ToUrl returns the proxy url, just for git clone
469	func (cfg *DownloaderProxyConfig) ToUrl() *url.URL {
470		if cfg == nil || cfg.Enable == false {
471			return nil
472		}
473		if cfg.System {
474			safeProxyReloadConf()
475			static := ieproxy.GetConf().Static
476			if static.Active && len(static.Protocols) > 0 {
477				// If only one protocol, use it
478				if len(static.Protocols) == 1 {
479					for _, v := range static.Protocols {
480						return parseUrlSafe(v)
481					}
482				}
483				// Check https
484				if v, ok := static.Protocols["https"]; ok {
485					return parseUrlSafe(v)
486				}
487				// Check http
488				if v, ok := static.Protocols["http"]; ok {
489					return parseUrlSafe(v)
490				}
491			}
492			return nil
493		}
494		if cfg.Scheme == "" || cfg.Host == "" {
495			return nil
496		}
497		return util.BuildProxyUrl(cfg.Scheme, cfg.Host, cfg.Usr, cfg.Pwd)
498	}
499	
500	var prcLock sync.Mutex
501	
502	func safeProxyReloadConf() {
503		prcLock.Lock()
504		defer prcLock.Unlock()
505	
506		ieproxy.ReloadConf()
507	}
508	
509	func parseUrlSafe(rawUrl string) *url.URL {
510		u, err := url.Parse(rawUrl)
511		if err != nil {
512			return nil
513		}
514		return u
515	}
