	if opts != nil && opts.Size > 0 {
		f.connMu.Lock()
		f.meta.Opts.Size = opts.Size
		if f.meta.Res != nil && !f.hasKnownSize() {
			f.setResourceSizeLocked(0, false)
		}
		f.connMu.Unlock()
	}
	// Patch request info
	if req != nil {
		if req.URL != "" {
			f.meta.Req.URL = req.URL
			// Clear redirect URL when URL is changed, so new requests use the new URL
			f.updateRedirectURL("")
		}
